intentos.respuesta_cruda:
{
  "sql": "SELECT t1.product_category_name_english, AVG(t2.review_score) AS avg_review_score, AVG(CASE WHEN t2.order_delivered_customer_date > t2.order_estimated_delivery_date THEN 1 ELSE 0 END) AS pct_late FROM product_category_translation t1 LEFT JOIN vw_ventas_pedido t2 ON t1.product_category_name = t2.categoria_ingles GROUP BY t1.product_category_name_english HAVING COUNT(t2.review_id) >= 100 AND AVG(t2.review_score) < (SELECT AVG(review_score) FROM vw_ventas_pedido) AND AVG(CASE WHEN t2.order_delivered_customer_date > t2.order_estimated_delivery_date THEN 1 ELSE 0 END) < (SELECT AVG(CASE WHEN order_delivered_customer_date > order_estimated_delivery_date THEN 1 ELSE 0 END) FROM vw_entregas_retrasos WHERE order_delivered_customer_date IS NOT NULL)"
}
